ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_private *priv;
    ssize_t bytes_read = 0;
    int ret;

    priv = file->private_data;
    if (!priv)
        return -EINVAL;

    if (!priv->queue_head)
        return -ENODATA;

    mutex_lock(&priv->lock);

    while (bytes_read < count && priv->queue_head) {
        struct timer_data *data = priv->queue_head;

        if (data->disconnected) {
            mutex_unlock(&priv->lock);
            return -EPIPE;
        }

        if (signal_pending(current)) {
            mutex_unlock(&priv->lock);
            return -ERESTARTSYS;
        }

        if (!data->available) {
            wait_queue_t wait;
            prepare_to_wait(&priv->wait_queue, &wait, TASK_INTERRUPTIBLE);
            mutex_unlock(&priv->lock);
            schedule();
            mutex_lock(&priv->lock);
            finish_wait(&priv->wait_queue, &wait);
            continue;
        }

        if (copy_to_user(buffer + bytes_read, data->payload, data->size)) {
            mutex_unlock(&priv->lock);
            return -EFAULT;
        }

        bytes_read += data->size;
        priv->queue_head = data->next;
        kfree(data);
    }

    mutex_unlock(&priv->lock);
    return bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_private *priv = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!priv) {
        return -EINVAL;
    }

    mutex_lock(&priv->lock);

    while (bytes_read < (ssize_t)count) {
        if (priv->disconnected) {
            ret = -EPIPE;
            break;
        }

        if (priv->queue_head == priv->queue_tail) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                break;
            }

            ret = wait_event_interruptible(priv->wait_queue, 
                                           (priv->queue_head != priv->queue_tail) || priv->disconnected);
            if (ret < 0) {
                break;
            }
            continue;
        }

        size_t bytes_available = priv->queue[priv->queue_tail] - priv->read_pos;
        size_t bytes_to_copy = min(bytes_available, count - bytes_read);

        if (copy_to_user(buffer + bytes_read, 
                         priv->buffer + priv->queue[priv->queue_tail] + priv->read_pos, 
                         bytes_to_copy)) {
            ret = -EFAULT;
            break;
        }

        bytes_read += bytes_to_copy;
        priv->read_pos += bytes_to_copy;

        if (priv->read_pos == priv->queue[priv->queue_tail]) {
            priv->queue_tail = (priv->queue_tail + 1) % SOUND_TIMER_QUEUE_SIZE;
            priv->read_pos = 0;
        }
    }

    mutex_unlock(&priv->lock);
    return (ret < 0) ? ret : bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    struct sound_timer_private *priv;
    ssize_t bytes_read = 0;
    int ret;

    if (!file || !buffer || !count || !offset)
        return -EINVAL;

    priv = file->private_data;
    if (!priv)
        return -EFAULT;

    if (!try_module_get(priv->owner))
        return -ENODEV;

    spin_lock(&priv->lock);

    while (bytes_read < (ssize_t)count) {
        struct timer_data *data;

        if (priv->disconnected) {
            ret = -ENODEV;
            goto out_unlock;
        }

        if (priv->queue_head == priv->queue_tail) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                goto out_unlock;
            }

            ret = wait_event_interruptible(priv->wait_queue,
                                           (priv->queue_head != priv->queue_tail) || priv->disconnected);
            if (ret)
                goto out_unlock;
        }

        if (priv->disconnected) {
            ret = -ENODEV;
            goto out_unlock;
        }

        data = &priv->data_queue[priv->queue_head];
        if (copy_to_user(buffer + bytes_read, data, sizeof(*data))) {
            ret = -EFAULT;
            goto out_unlock;
        }

        priv->queue_head = (priv->queue_head + 1) % SOUND_TIMER_QUEUE_SIZE;
        bytes_read += sizeof(*data);
    }

    ret = bytes_read;
out_unlock:
    spin_unlock(&priv->lock);

    module_put(priv->owner);

    if (ret < 0)
        return ret;

    return bytes_read;
}

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_data *data = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!data)
        return -EFAULT;

    spin_lock(&data->lock);

    while (bytes_read < (ssize_t)count) {
        struct timer_event *event;

        if (kthread_should_stop() || data->disconnected) {
            ret = -ENODEV;
            break;
        }

        if (data->queue_head == data->queue_tail) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                break;
            }

            wait_event_interruptible(data->wait_queue,
                                     data->queue_head != data->queue_tail || kthread_should_stop() || data->disconnected);

            if (kthread_should_stop() || data->disconnected) {
                ret = -ENODEV;
                break;
            }
        }

        event = &data->events[data->queue_tail];
        if (copy_to_user(buffer + bytes_read, event, sizeof(struct timer_event))) {
            ret = -EFAULT;
            break;
        }

        data->queue_tail = (data->queue_tail + 1) % TIMER_QUEUE_SIZE;
        bytes_read += sizeof(struct timer_event);
    }

    spin_unlock(&data->lock);

    if (ret < 0)
        return ret;

    return bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_data *data = file->private_data;
    ssize_t bytes_read = 0;

    if (!data)
        return -EINVAL;

    if (mutex_lock_interruptible(&data->lock))
        return -ERESTARTSYS;

    while (count > 0 && !list_empty(&data->queue)) {
        struct timer_event *event = list_first_entry(&data->queue, struct timer_event, list);
        size_t event_size = sizeof(*event);

        if (event_size > count) {
            event_size = count;
        }

        if (copy_to_user(buffer, event, event_size)) {
            mutex_unlock(&data->lock);
            return -EFAULT;
        }

        buffer += event_size;
        count -= event_size;
        bytes_read += event_size;

        list_del(&event->list);
        kfree(event);
    }

    mutex_unlock(&data->lock);

    return bytes_read ? bytes_read : -EAGAIN;
}
